func (c *Context) SyscallNo() uint {
	return uint(c.regs.A7)
}

// Arg0 gets the arg0 for the current syscall
func (c *Context) Arg0() uint {
	return uint(c.regs.A0)
}

// Arg1 gets the arg1 for the current syscall
